  "schemaVersion": 1,
  "characterId": "he",
  "lastUpdatedChapterRef": "chapter:chapter-003.md",
  "factsKnown": [
    {
      "id": "he-initial",
      "summary": "仅她知道药箱暗格有蓝签账页；她尚未透露",
      "sourceChapterRef": "chapter:chapter-001.md"
    },
    {
      "summary": "绞盘仍有摩擦，叶澄决定岸上复查五分钟；只有若无异响才可能沿正规水道启航，药箱仍冷藏且铅封未动。",
      "id": "45b725ea-8665-4cdd-9277-ceb0edc8bd56"
    }
  ],
  "emotionalMemory": [
    {
      "summary": "担心延误伤及诊所病人，也警惕岑寂把延误和账页捆在一起施压。",
      "id": "92fe4fea-6762-4713-afb2-50543910dab7"
    }
  ],
  "relationshipDeltas": [
    {
      "summary": "认可苏砚坚持不搜查、不凭怀疑拘人，也信任叶澄以安全为先的判断。",
      "id": "935e9b7e-cf20-4f5a-b1b4-6be47c975298"
    }
  ],
  "unresolvedIntentions": [
    {
      "id": "he-goal",
      "summary": "把冷藏药送到灯塔诊所"
    },
    {
      "summary": "守住暗格秘密和药箱封存，争取把冷藏药送到灯塔诊所。",
      "id": "b20bc40f-14ad-4d19-aa52-74814fb94959"
    }
  ],
  "privateMisbeliefs": []
}

